CREATE TABLE trade_refund (id BIGINT PRIMARY KEY,refund_no VARCHAR(64) NOT NULL,payment_id BIGINT NOT NULL,order_id BIGINT NOT NULL,order_item_id BIGINT NOT NULL,aftersale_id VARCHAR(64) NOT NULL,quantity INT NOT NULL,amount DECIMAL(18,2) NOT NULL,status VARCHAR(32) NOT NULL,channel_refund_no VARCHAR(96) NULL,created_at TIMESTAMP(3) NOT NULL,updated_at TIMESTAMP(3) NOT NULL,succeeded_at TIMESTAMP(3) NULL,UNIQUE KEY uk_refund_no(refund_no),UNIQUE KEY uk_refund_aftersale(aftersale_id),KEY idx_refund_item(order_item_id,status));
